1	import * as THREE from 'three';
2	import { CONFIG } from '../../config';
3	import { shared } from '../../core/shared';
4	import { PP_FLAG } from './kinds';
5	import type { CrowdData, CrowdClip, CrowdClipName } from './crowdData';
6	import type { Walker } from '../people';
7	
8	/* =====================================================================
9	   ĐÁM ĐÔNG NGƯỜI THẬT (D-032) — mỗi hệ người đi bộ một THREE.BatchedMesh (r165, WEBGL_multi_draw ⇒ 1 lệnh vẽ), một id mỗi người.
10	   Spec: docs/superpowers/specs/2026-11-12-dam-dong-nguoi-that-design.md §4, §5. Dữ liệu: crowdData.ts (định dạng crowd.bin ở đầu file đó).
11	   - Skin trong vertex shader: 2 xương mỗi đỉnh (aBones, aW), ma trận 3×4 của xương đọc từ texture chuyển động (uCrowdAnim, texelFetch),
12	     nội suy hai khung liền nhau; đoạn lặp thì khung cuối nội suy về khung đầu, đoạn không lặp (photo) giữ khung cuối.
13	   - Thông số từng người (hàng đầu đoạn, ±số khung, khung/giây, pha theo khung) nằm trong một DataTexture float dùng chung cho cả 3 hệ
14	     (uCrowdPeople). Chỉ số của người trong texture đó (= chỗ bắt đầu của hệ + id) ghi vào kênh alpha của batchingColorTexture
15	     (setColorAt chỉ ghi rgb; rgb = hệ số sáng theo người, spec §4.11). Một vật liệu cho cả 3 hệ ⇒ không có uniform riêng theo hệ.
16	   - Thời gian: shared.uTime; lấy mod theo chu kỳ của người TRƯỚC khi nhân khung/giây để pha không mất chính xác khi trang chạy lâu.
17	   - Phải setColorAt cho mọi id (r165: thiếu bảng màu thì renderer tra lại program mỗi khung). sortObjects = false; không setInstanceCountAt.
18	   - Ẩn người: setVisibleAt (tự đặt _visibilityChanged). setMatrixAt tự đặt matricesTexture.needsUpdate.
19	   - Khối cầu bao từng id: của lưới nguồn, nới cullPad / tỉ lệ người (đơn vị cục bộ; matrix nhân lại tỉ lệ) để tay chân không bị cắt nhầm.
20	   ===================================================================== */
21	const PEOPLE_W = 32, PEOPLE_H = 32;   // texel — sức chứa texture thông số: 1 024 người cho mọi hệ (hiện 226)
22	
23	/* ---------- băm theo chỉ số (không dùng rand / rnd / rng) ---------- */
24	const crHashStr = (s: string): number => { let h = 2166136261; for (let k = 0; k < s.length; k++) h = Math.imul(h ^ s.charCodeAt(k), 16777619); return h >>> 0; };
25	const crHash = (a: number, b: number): number => {
26	  let h = Math.imul(a ^ Math.imul((b + 0x9e3779b9) | 0, 0x85ebca6b), 0xc2b2ae35);
27	  h ^= h >>> 16; h = Math.imul(h, 0x7feb352d); h ^= h >>> 15; h = Math.imul(h, 0x846ca68b); h ^= h >>> 16;
28	  return (h >>> 0) / 4294967296;
29	};
30	
31	/* Dùng được người thật không: có dữ liệu và có WEBGL_multi_draw (thiếu thì r165 vẽ mỗi người một lệnh ⇒ lùi về hình khối) */
32	export function crowdUsable(data: CrowdData | null, hasMultiDraw: boolean): boolean {
33	  return !!data && hasMultiDraw && data.chars.some((c) => c.child) && data.chars.some((c) => !c.child);
34	}
35	
36	/* Chọn nhân vật cho người i của hệ system (tất định). isChild → chỉ nhân vật trẻ em; avoid: nhân vật của người đi cùng (−1 nếu không), tránh trùng khi có ≥ 2 lựa chọn */
37	export function crowdPick(chars: { child: boolean }[], system: string, i: number, isChild: boolean, avoid: number): number {
38	  let cand: number[] = [];
39	  chars.forEach((c, k) => { if (c.child === isChild) cand.push(k); });
40	  if (!cand.length) cand = chars.map((_, k) => k);
41	  let k = Math.floor(crHash(crHashStr(system), i) * cand.length);
42	  if (cand[k] === avoid && cand.length > 1) k = (k + 1) % cand.length;
43	  return cand[k];
44	}
45	
46	/* Nhịp phát chuyển động = tốc độ người ÷ (tốc độ tự nhiên của đoạn × tỉ lệ người), kẹp [rateMin, rateMax] (spec §4.5). natural = 0 (đứng) → 1 */
47	export function crowdRate(speed: number, natural: number, scale: number): number {
48	  const C = CONFIG.people.crowd;
49	  if (!(natural > 0)) return 1;
50	  return Math.min(C.rateMax, Math.max(C.rateMin, speed / (natural * scale)));
51	}
52	
53	/* Khung (số thực) trong [0, frames) tại thời điểm t (s); phase: pha chu kỳ, rad (Walker.phase). Bản CPU của công thức trong shader (VS_SKIN) */
54	export function crowdFrame(t: number, clip: CrowdClip, rate: number, phase: number): number {
55	  const N = clip.frames;
56	  if (!clip.loop) return N - 1;
57	  const fr = clip.fps * rate, T = N / fr, ph = crPhase(phase, N);
58	  const f = ((t % T) * fr + ph) % N;
59	  return f < 0 ? f + N : f;
60	}
61	const crPhase = (phase: number, N: number) => ((((phase / (2 * Math.PI)) % 1) + 1) % 1) * N;   // rad → khung, [0, N)
62	export const crClip = (w: Walker): CrowdClipName => (w.kind === 'run' ? 'jog' : w.kind === 'stand' ? ((w.flags ?? 0) & PP_FLAG.photo ? 'photo' : 'idle') : 'walk');
63	
64	/* ---------- shader ---------- */
65	const VS_PARS = /* glsl */`#include <batching_pars_vertex>
66	uniform highp sampler2D uCrowdAnim;
67	uniform highp sampler2D uCrowdPeople;
68	uniform float uTime;
69	attribute vec2 aBones;
70	attribute float aW;
71	vec4 crRow( int c, int f0, int f1, float t ) { return mix( texelFetch( uCrowdAnim, ivec2( c, f0 ), 0 ), texelFetch( uCrowdAnim, ivec2( c, f1 ), 0 ), t ); }
72	`;
73	// thay beginnormal_vertex: tính 3 hàng ma trận skin (crR0..2) một lần, dùng lại ở begin_vertex
74	const VS_SKIN = /* glsl */`
75	vec4 crR0 = vec4( 1.0, 0.0, 0.0, 0.0 ), crR1 = vec4( 0.0, 1.0, 0.0, 0.0 ), crR2 = vec4( 0.0, 0.0, 1.0, 0.0 );
76	#if defined( USE_BATCHING ) && defined( USE_BATCHING_COLOR )
77	{
78	  int crCs = textureSize( batchingColorTexture, 0 ).x, crId = int( batchId );
79	  int crG = int( texelFetch( batchingColorTexture, ivec2( crId % crCs, crId / crCs ), 0 ).a + 0.5 );   // chỉ số người trong uCrowdPeople
80	  int crPw = textureSize( uCrowdPeople, 0 ).x;
81	  vec4 crP = texelFetch( uCrowdPeople, ivec2( crG % crPw, crG / crPw ), 0 );   // x hàng đầu đoạn, y ±số khung (âm: giữ khung cuối), z khung/giây, w pha (khung)
82	  int crN = int( abs( crP.y ) + 0.5 ), f0 = crN - 1, f1 = crN - 1; float ft = 0.0;
83	  if ( crP.y > 0.0 ) {
84	    float crF = mod( mod( uTime, crP.y / crP.z ) * crP.z + crP.w, crP.y );   // mod theo chu kỳ trước: uTime lớn không làm mất chính xác pha
85	    f0 = min( int( crF ), crN - 1 ); f1 = f0 + 1 >= crN ? 0 : f0 + 1; ft = fract( crF );
86	  }
87	  int crRw = int( crP.x + 0.5 ); f0 += crRw; f1 += crRw;
88	  int b0 = int( aBones.x + 0.5 ) * 3, b1 = int( aBones.y + 0.5 ) * 3; float w1 = 1.0 - aW;
89	  crR0 = crRow( b0, f0, f1, ft ) * aW + crRow( b1, f0, f1, ft ) * w1;
90	  crR1 = crRow( b0 + 1, f0, f1, ft ) * aW + crRow( b1 + 1, f0, f1, ft ) * w1;
91	  crR2 = crRow( b0 + 2, f0, f1, ft ) * aW + crRow( b1 + 2, f0, f1, ft ) * w1;
92	}
93	#endif
94	vec3 objectNormal = vec3( dot( crR0.xyz, normal ), dot( crR1.xyz, normal ), dot( crR2.xyz, normal ) );
95	#ifdef USE_TANGENT
96	vec3 objectTangent = vec3( tangent.xyz );
97	#endif
98	`;
99	const VS_POS = /* glsl */`vec4 crPos = vec4( position, 1.0 );
100	vec3 transformed = vec3( dot( crR0, crPos ), dot( crR1, crPos ), dot( crR2, crPos ) );
101	#ifdef USE_ALPHAHASH
102	vPosition = vec3( position );
103	#endif
104	`;
105	
106	type CrowdState = { people: THREE.DataTexture; next: number };
107	const mats = new WeakMap<CrowdData, THREE.MeshStandardMaterial>();
108	/* Một vật liệu dùng chung cho 3 hệ (theo bộ dữ liệu). Texture trong uniform (uCrowdAnim, uCrowdPeople) không được prewarm tải trước:
109	   bên dựng gọi renderer.initTexture (people.ts) */
110	export function crowdMaterial(data: CrowdData): THREE.MeshStandardMaterial {
111	  const old = mats.get(data); if (old) return old;
112	  const m = new THREE.MeshStandardMaterial({ map: data.atlas, roughness: CONFIG.people.roughness, metalness: 0 });
113	  m.name = 'peopleCrowd';
114	  const people = new THREE.DataTexture(new Float32Array(PEOPLE_W * PEOPLE_H * 4), PEOPLE_W, PEOPLE_H, THREE.RGBAFormat, THREE.FloatType);
115	  people.minFilter = people.magFilter = THREE.NearestFilter; people.generateMipmaps = false; people.name = 'peopleCrowdParams'; people.needsUpdate = true;
116	  const state: CrowdState = { people, next: 0 };
117	  m.userData.crowd = state;
118	  m.onBeforeCompile = (s) => {
119	    s.uniforms.uTime = shared.uTime; s.uniforms.uCrowdAnim = { value: data.anim }; s.uniforms.uCrowdPeople = { value: people };
120	    s.vertexShader = s.vertexShader.replace('#include <batching_pars_vertex>', VS_PARS).replace('#include <beginnormal_vertex>', VS_SKIN).replace('#include <begin_vertex>', VS_POS);
121	    m.userData.vs = s.vertexShader;
122	  };
123	  m.customProgramCacheKey = () => 'peopleCrowd';
124	  mats.set(data, m);
125	  return m;
126	}
127	/* Texture thông số theo người của vật liệu (cho renderer.initTexture) */
128	export const crowdParams = (m: THREE.Material): THREE.DataTexture => (m.userData.crowd as CrowdState).people;
129	
130	/* Thông tin theo id (móc kiểm thử, stepPeople): nhân vật, có nón, tỉ lệ người (m/m so với lưới), tổng tam giác */
131	export interface CrowdInfo { char: Int16Array; hat: Uint8Array; scale: Float32Array; tris: number }
132	
133	/* Dựng một hệ: một id mỗi người theo thứ tự list. Tỉ lệ người lớn = heightScale × Walker.scale; trẻ em (Walker.scale = childScale) = heightScale
134	   (nhân vật trẻ em đã thấp sẵn, spec §4.10). Cờ nón + nhân vật có bản nón → lưới hat. Không gọi rnd() / rand() / rng */
135	export function crowdBuild(data: CrowdData, list: Walker[], system: string): THREE.BatchedMesh {
136	  const P = CONFIG.people, C = P.crowd, mat = crowdMaterial(data), st = mat.userData.crowd as CrowdState, n = list.length;
137	  if (st.next + n > PEOPLE_W * PEOPLE_H) throw new Error('crowd: hết chỗ trong texture thông số người');
138	  const char = new Int16Array(n), hat = new Uint8Array(n), scale = new Float32Array(n), geos: THREE.BufferGeometry[] = [];
139	  let nv = 0, ni = 0;
140	  list.forEach((w, i) => {
141	    const child = w.scale === P.childScale, lead = w.follow ?? -1;
142	    char[i] = crowdPick(data.chars, system, i, child, lead >= 0 && lead < i ? char[lead] : -1);
143	    const ch = data.chars[char[i]], useHat = !!((w.flags ?? 0) & PP_FLAG.hat) && !!ch.hat, src = useHat ? ch.hat : ch.geometry;
144	    hat[i] = useHat ? 1 : 0;
145	    scale[i] = C.heightScale * (child ? 1 : (w.scale ?? 1));
146	    // vỏ dùng chung attribute của lưới nguồn (addGeometry chép dữ liệu), chỉ khác khối cầu bao đã nới
147	    const g = new THREE.BufferGeometry();
148	    for (const k of Object.keys(src.attributes)) g.setAttribute(k, src.attributes[k]);
149	    g.setIndex(src.index); g.boundingBox = src.boundingBox;
150	    g.boundingSphere = src.boundingSphere.clone(); g.boundingSphere.radius += C.cullPad / scale[i];
151	    geos.push(g); nv += src.getAttribute('position').count; ni += src.index.count;
152	  });
153	  const mesh = new THREE.BatchedMesh(n, nv, ni, mat), col = new THREE.Color(), pd = st.people.image.data as unknown as Float32Array, base = st.next, sysH = crHashStr(system) ^ 0x5bd1e995;
154	  st.next += n;
155	  geos.forEach((g, i) => {
156	    const id = mesh.addGeometry(g), w = list[i], name = crClip(w), clip = data.chars[char[i]].clips[name];
157	    mesh.setColorAt(id, col.setScalar(C.tint[0] + (C.tint[1] - C.tint[0]) * crHash(sysH, i)));   // hệ số sáng theo người (spec §4.11); bắt buộc cho mọi id
158	    const rate = name === 'walk' || name === 'jog' ? crowdRate(w.speed, clip.speed, scale[i]) : 1;
159	    pd.set([clip.row, clip.loop ? clip.frames : -clip.frames, clip.fps * rate, crPhase(w.phase ?? 0, clip.frames)], (base + id) * 4);
160	  });
161	  const colors = (mesh as unknown as { _colorsTexture: THREE.DataTexture })._colorsTexture, cd = colors.image.data as unknown as Float32Array;
162	  for (let i = 0; i < n; i++) cd[i * 4 + 3] = base + i;   // kênh alpha: chỉ số người trong uCrowdPeople
163	  colors.needsUpdate = true; st.people.needsUpdate = true;
164	  mesh.sortObjects = false; mesh.perObjectFrustumCulled = true; mesh.frustumCulled = false;   // bao cầu cả đối tượng không tự cập nhật: bên gọi đặt nếu cần (Cầu Rồng)
165	  mesh.castShadow = mesh.receiveShadow = false;
166	  mesh.userData.crowd = { char, hat, scale, tris: ni / 3 } satisfies CrowdInfo;
167	  return mesh;
168	}
169

1	/* ===== Dữ liệu đám đông người thật (D-032): đọc public/people/crowd.bin + crowd.jpg ===== */
2	/* Spec: docs/superpowers/specs/2026-11-12-dam-dong-nguoi-that-design.md §4; sinh bằng npm run gen:crowd (scripts/people/crowd.py).
3	   10 nhân vật Rocketbox (MIT) giản lược ≤ 1 600 tam giác, 22 xương, 2 xương mỗi đỉnh; chuyển động nướng thành ma trận xương.
4	   Hệ toạ độ của lưới: mét, +Y lên, mặt hướng +X, chân y = 0, tư thế nghỉ chữ T / chữ A (cần skin mới ra dáng đi).
5	
6	   Định dạng crowd.bin (little-endian), phiên bản 1:
7	     0   4 byte  'DNCR'
8	     4   u32     phiên bản (1)
9	     8   u32     J = số byte phần JSON (đệm dấu cách tới bội 4)
10	     12  J byte  JSON utf-8: { bones, boneNames, anim: { width, height, offset, bytes }, source,
11	                 chars: [{ id, child, female, height, verts, tris, hatVerts, hatTris, pos, nrm, uv, bones, w, idx,
12	                           clips: { walk|jog|idle|photo: { row, frames, fps, loop, speed } } }] }
13	                 pos … idx là offset byte (tính từ đầu khối nhị phân) của từng mảng.
14	     12+J        khối nhị phân, mỗi mảng bắt đầu ở bội 4:
15	                 pos f32 ×3, nrm f32 ×3, uv f32 ×2, bones u8 ×2, w f32 ×1, idx u16 ×3 mỗi tam giác.
16	                 Đỉnh 0..verts−1 và tam giác 0..tris−1 là người; hatVerts / hatTris nối tiếp là nón lá (index trỏ vào mảng
17	                 đỉnh chung, gắn cứng xương đầu: bones = [đầu, đầu], w = 1). Bản đội nón = toàn bộ mảng.
18	                 anim: u16 (half-float) RGBA, width = bones × 3 texel, mỗi hàng một khung; texel (b × 3 + j) = hàng j của
19	                 ma trận 3×4 xương b, đưa đỉnh từ tư thế nghỉ sang tư thế khung (cùng hệ toạ độ lưới):
20	                   p' = Σ_k w_k · (dot(T[b_k·3], p1), dot(T[b_k·3+1], p1), dot(T[b_k·3+2], p1)), p1 = (p, 1); pháp tuyến dùng .xyz.
21	   uv: toạ độ trong atlas crowd.jpg với v = 0 ở mép TRÊN của ảnh (texture.flipY = false, ImageBitmap không lật).
22	   Đoạn: walk / idle / photo 15 khung/giây, jog 30; loop = false (photo) thì giữ khung cuối. speed: m/s tự nhiên ở tỉ lệ 1
23	   khi phát đúng fps (0 với idle, photo). Trẻ em: không có bản nón (hat = null). */
24	import * as THREE from 'three';
25	import { CONFIG } from '../../config';
26	
27	export type CrowdClipName = 'walk' | 'jog' | 'idle' | 'photo';
28	export interface CrowdClip { row: number; frames: number; fps: number; loop: boolean; speed: number }   // row: hàng đầu của đoạn trong texture chuyển động; speed: m/s tự nhiên ở tỉ lệ 1 (0 với idle, photo)
29	export interface CrowdChar {
30	  id: string;            // tên Rocketbox
31	  child: boolean; female: boolean;
32	  height: number;        // m, ở tỉ lệ 1
33	  geometry: THREE.BufferGeometry;           // position (Float32 ×3), normal (×3), uv (×2, toạ độ trong atlas), aBones (Uint8 ×2), aW (Float32 ×1: trọng số xương thứ nhất), có index
34	  hat: THREE.BufferGeometry | null;         // cùng bộ attribute, thêm nón lá; null với trẻ em
35	  clips: Record<CrowdClipName, CrowdClip>;
36	}
37	export interface CrowdParsed { chars: CrowdChar[]; bones: number; animWidth: number; animHeight: number; animData: Uint16Array; maxVerts: number; maxIndices: number }   // animData: RGBA half-float, mỗi hàng một khung, 3 texel mỗi xương
38	export interface CrowdData extends CrowdParsed { anim: THREE.DataTexture; atlas: THREE.Texture }
39	
40	const MAGIC = 'DNCR', VERSION = 1;
41	const CLIP_NAMES: CrowdClipName[] = ['walk', 'jog', 'idle', 'photo'];
42	
43	/* Pháp tuyến dài 0 trong tệp (Blender trả pháp tuyến góc 0 ở vài đỉnh sau giản lược: Female_Adult_03 có 5 đỉnh) ⇒ normalize() trong shader ra NaN,
44	   điểm ảnh đen, ban đêm bloom lan NaN ra cả khung. Thay bằng tổng pháp tuyến mặt (theo diện tích) của các tam giác dùng đỉnh đó; không có thì +Y. Sửa tại chỗ */
45	function crFixNormals(pos: Float32Array, nrm: Float32Array, idx: Uint16Array): void {
46	  const bad: number[] = [];
47	  for (let v = 0; v < nrm.length / 3; v++) if (Math.hypot(nrm[v * 3], nrm[v * 3 + 1], nrm[v * 3 + 2]) < 1e-6) bad.push(v);
48	  if (!bad.length) return;
49	  const acc = new Map<number, number[]>(bad.map((v) => [v, [0, 0, 0]]));
50	  for (let t = 0; t < idx.length; t += 3) {
51	    const a = idx[t], b = idx[t + 1], c = idx[t + 2];
52	    if (!acc.has(a) && !acc.has(b) && !acc.has(c)) continue;
53	    const ux = pos[b * 3] - pos[a * 3], uy = pos[b * 3 + 1] - pos[a * 3 + 1], uz = pos[b * 3 + 2] - pos[a * 3 + 2];
54	    const vx = pos[c * 3] - pos[a * 3], vy = pos[c * 3 + 1] - pos[a * 3 + 1], vz = pos[c * 3 + 2] - pos[a * 3 + 2];
55	    const n = [uy * vz - uz * vy, uz * vx - ux * vz, ux * vy - uy * vx];   // tích có hướng = 2 × diện tích × pháp tuyến mặt
56	    for (const k of [a, b, c]) { const s = acc.get(k); if (s) { s[0] += n[0]; s[1] += n[1]; s[2] += n[2]; } }
57	  }
58	  for (const [v, s] of acc) {
59	    const l = Math.hypot(s[0], s[1], s[2]);
60	    nrm.set(l > 1e-12 ? [s[0] / l, s[1] / l, s[2] / l] : [0, 1, 0], v * 3);
61	  }
62	}
