64	/* ===== Đọc tệp (thuần: không DOM, không fetch; chạy được trong node) ===== */
65	export function crowdParse(buf: ArrayBuffer): CrowdParsed {
66	  if (buf.byteLength < 12) throw new Error('crowd.bin: tệp quá ngắn');
67	  const head = new Uint8Array(buf, 0, 4), dv = new DataView(buf);
68	  if (String.fromCharCode(...head) !== MAGIC) throw new Error('crowd.bin: sai magic');
69	  const ver = dv.getUint32(4, true); if (ver !== VERSION) throw new Error(`crowd.bin: phiên bản ${ver} (cần ${VERSION})`);
70	  const J = dv.getUint32(8, true); if (12 + J > buf.byteLength || J % 4) throw new Error('crowd.bin: phần JSON hỏng');
71	  const meta = JSON.parse(new TextDecoder().decode(new Uint8Array(buf, 12, J)));
72	  const base = 12 + J;
73	  const view = <T>(C: { new (b: ArrayBuffer, o: number, n: number): T; BYTES_PER_ELEMENT: number }, off: number, n: number): T => {
74	    if (off % C.BYTES_PER_ELEMENT || base + off + n * C.BYTES_PER_ELEMENT > buf.byteLength) throw new Error('crowd.bin: mảng vượt tệp');
75	    return new C(buf, base + off, n);
76	  };
77	  const bones: number = meta.bones;
78	  let maxVerts = 0, maxIndices = 0;
79	  const chars: CrowdChar[] = meta.chars.map((c) => {
80	    const nv = c.verts + c.hatVerts, ni = (c.tris + c.hatTris) * 3;
81	    const pos = view(Float32Array, c.pos, nv * 3), nrm = view(Float32Array, c.nrm, nv * 3), uv = view(Float32Array, c.uv, nv * 2);
82	    const bi = view(Uint8Array, c.bones, nv * 2), w = view(Float32Array, c.w, nv), idx = view(Uint16Array, c.idx, ni);
83	    crFixNormals(pos, nrm, idx);
84	    const geo =(v: number, i: number): THREE.BufferGeometry => {
85	      const g = new THREE.BufferGeometry();
86	      g.setAttribute('position', new THREE.BufferAttribute(pos.subarray(0, v * 3), 3));
87	      g.setAttribute('normal', new THREE.BufferAttribute(nrm.subarray(0, v * 3), 3));
88	      g.setAttribute('uv', new THREE.BufferAttribute(uv.subarray(0, v * 2), 2));
89	      g.setAttribute('aBones', new THREE.BufferAttribute(bi.subarray(0, v * 2), 2));
90	      g.setAttribute('aW', new THREE.BufferAttribute(w.subarray(0, v), 1));
91	      g.setIndex(new THREE.BufferAttribute(idx.subarray(0, i), 1));
92	      g.computeBoundingBox(); g.computeBoundingSphere();
93	      maxVerts = Math.max(maxVerts, v); maxIndices = Math.max(maxIndices, i);
94	      return g;
95	    };
96	    const clips = {} as Record<CrowdClipName, CrowdClip>;
97	    for (const n of CLIP_NAMES) {
98	      const k = c.clips?.[n]; if (!k) throw new Error(`crowd.bin: ${c.id} thiếu đoạn ${n}`);
99	      clips[n] = { row: k.row, frames: k.frames, fps: k.fps, loop: !!k.loop, speed: k.speed };
100	    }
101	    return { id: c.id, child: !!c.child, female: !!c.female, height: c.height, geometry: geo(c.verts, c.tris * 3), hat: c.hatVerts > 0 ? geo(nv, ni) : null, clips };
102	  });
103	  const a = meta.anim;
104	  if (a.width !== bones * 3 || a.bytes !== a.width * a.height * 8) throw new Error('crowd.bin: kích thước texture chuyển động sai');
105	  const animData = view(Uint16Array, a.offset, a.width * a.height * 4);
106	  return { chars, bones, animWidth: a.width, animHeight: a.height, animData, maxVerts, maxIndices };
107	}
