109	/* ===== Tải trong trình duyệt ===== */
110	let loaded: CrowdData | null = null;
111	let pending: Promise<CrowdData | null> | null = null;
112	
113	// Kết quả của lần crowdLoad đã xong (null nếu chưa xong, lỗi, hoặc ?crowd=off)
114	export function crowdGet(): CrowdData | null { return loaded; }
115	
116	// Tải bin + jpg theo BASE_URL, tối đa CONFIG.people.crowd.loadTimeoutMs; lỗi bất kỳ → console.warn một lần, trả null.
117	// ?crowd=off → null ngay, không gửi yêu cầu nào. Gọi nhiều lần dùng chung một lượt tải.
118	export function crowdLoad(): Promise<CrowdData | null> {
119	  if (pending) return pending;
120	  if (typeof location !== 'undefined' && new URLSearchParams(location.search).get('crowd') === 'off') return (pending = Promise.resolve(null));
121	  pending = (async () => {
122	    const C = CONFIG.people.crowd, ctl = new AbortController();
123	    let timer: ReturnType<typeof setTimeout> | undefined;
124	    const timeout = new Promise<never>((_, rej) => { timer = setTimeout(() => { ctl.abort(); rej(new Error(`quá ${C.loadTimeoutMs} ms`)); }, C.loadTimeoutMs); });
125	    const work = (async (): Promise<CrowdData> => {
126	      const base = import.meta.env.BASE_URL;
127	      const [rb, ri] = await Promise.all([fetch(base + C.bin, { signal: ctl.signal }), fetch(base + C.atlas, { signal: ctl.signal })]);
128	      if (!rb.ok || !ri.ok) throw new Error(`HTTP ${rb.status} / ${ri.status}`);
129	      const [buf, blob] = await Promise.all([rb.arrayBuffer(), ri.blob()]);
130	      const parsed = crowdParse(buf);
131	      const bmp = await createImageBitmap(blob);
132	      const atlas = new THREE.Texture(bmp);
133	      atlas.flipY = false; atlas.colorSpace = THREE.SRGBColorSpace; atlas.name = 'peopleCrowdAtlas'; atlas.needsUpdate = true;
134	      const anim = new THREE.DataTexture(parsed.animData as Uint16Array<ArrayBuffer>, parsed.animWidth, parsed.animHeight, THREE.RGBAFormat, THREE.HalfFloatType);
135	      anim.minFilter = anim.magFilter = THREE.NearestFilter; anim.generateMipmaps = false; anim.name = 'peopleCrowdAnim'; anim.needsUpdate = true;
136	      return { ...parsed, anim, atlas };
137	    })();
138	    work.catch(() => {}); timeout.catch(() => {});
139	    try {
140	      loaded = await Promise.race([work, timeout]);
141	    } catch (e) {
142	      console.warn('[people] không dùng được đám đông người thật, dùng hình khối:', e instanceof Error ? e.message : e);
143	      loaded = null;
144	    } finally { clearTimeout(timer); }
145	    return loaded;
146	  })();
147	  return pending;
148	}
