13	/* =====================================================================
14	   NGƯỜI ĐI BỘ — hệ dùng chung cho Trần Thị Lý, Cầu sông Hàn, Cầu Rồng (spec G5–G10).
15	   Mỗi hệ: 1 InstancedMesh, hình gộp ppBuildGeometry(), vật liệu ppMaterial() (tay chân vung trong vertex shader theo shared.uTime).
16	   CPU chỉ dời vị trí, quay hướng; dáng đi / chạy / đứng theo thuộc tính instance aVar (pha, biên độ, cờ, nhịp) và aPants (màu quần).
17	   Mỗi người: { x, z, lo, hi, dir, speed, profile(c) → cao độ chân, axis: 'x' | 'z' } + kiểu người (ppApplyKinds).
18	   Người thật (D-032, real = true): khi đã tải được dữ liệu đám đông (crowdLoad trong main.ts) và có WEBGL_multi_draw, mỗi hệ là một
19	   THREE.BatchedMesh (common/people/crowd.ts, 1 lệnh vẽ); ẩn người bằng setVisibleAt. Không thì đường hình khối trên giữ nguyên (đường lùi).
20	   ===================================================================== */
21	export interface Walker {
22	  x: number; z: number; lo: number; hi: number; dir: number; speed: number; profile: (c: number) => number; axis?: 'x' | 'z';
23	  kind?: PersonKind; scale?: number; flags?: number; phase?: number;
24	  face?: number;     // rad quanh Y, chỉ cho người đứng (0: mặt hướng +X)
25	  follow?: number;   // chỉ số người dẫn (người đi cùng / trẻ em), chép vị trí dọc dải của người đó
26	}
27	export interface People { list: Walker[]; mesh: THREE.InstancedMesh | THREE.BatchedMesh; group: THREE.Group; real: boolean }
28	
29	/* Băm theo chỉ số → [0, 1) (không đụng chuỗi ngẫu nhiên nào) */
30	const ppHash = (k: number) => { const s = Math.sin(k * 12.9898 + 78.233) * 43758.5453; return s - Math.floor(s); };
31	/* Góc quay quanh Y để hình (mặt hướng +X) nhìn ra phía z dương (s > 0) hoặc z âm */
32	export const ppFaceZ = (s: number) => (s > 0 ? -Math.PI / 2 : Math.PI / 2);
33	
34	/* Gộp danh sách kiểu người của nhiều đoạn (ppAssignKinds từng đoạn) thành một, dời chỉ số follow theo vị trí đoạn trong danh sách chung */
35	export function ppJoinKinds(...parts: PersonInfo[][]): PersonInfo[] {
36	  const out: PersonInfo[] = [];
37	  for (const p of parts) { const base = out.length; for (const k of p) out.push({ ...k, follow: k.follow >= 0 ? k.follow + base : -1 }); }
38	  return out;
39	}
40	
41	/* Gán kiểu người lên danh sách đã dựng (sau khi lấy hết rnd() của cầu, trước createPeople):
42	   người chạy nhận tốc độ chạy; người đi cùng chép vị trí, hướng, tốc độ, dải của người dẫn rồi lệch ngang companionGap về phía trong
43	   (về tim cầu với người đi dọc cầu, về phía sông với người đi dọc bờ; outward = true thì lệch ra ngoài, về phía lan can — Cầu Rồng, tránh hàng cột đèn);
44	   người đứng do từng cầu đặt sát lan can và quay mặt (place). */
45	export function ppApplyKinds(list: Walker[], infos: PersonInfo[], place: (w: Walker, info: PersonInfo, i: number) => void, outward = false): void {
46	  const P = CONFIG.people, [r0, r1] = P.run.speed;
47	  infos.forEach((info, i) => {
48	    const w = list[i];
49	    w.kind = info.kind; w.scale = info.scale; w.flags = info.flags; w.phase = info.phase;
50	    if (info.kind === 'run') w.speed = r0 + (r1 - r0) * ppHash(i + 0.5);
51	    if (info.follow >= 0) {
52	      const L = list[info.follow], lat = L.axis === 'z' ? 'x' : 'z';
53	      Object.assign(w, { x: L.x, z: L.z, dir: L.dir, speed: L.speed, lo: L.lo, hi: L.hi, axis: L.axis, profile: L.profile, follow: info.follow });
54	      w[lat] += (outward ? 1 : -1) * Math.sign(w[lat]) * P.companionGap;
55	    }
56	    if (info.kind === 'stand') place(w, info, i);
57	  });
58	}
