60	export function createPeople(bridge: { group: THREE.Object3D; noReflect: THREE.Object3D[] }, list: Walker[], name: string, rnd: () => number): People {
61	  const P = CONFIG.people, n = list.length, crowd = crowdGet(), real = crowdUsable(crowd, renderer.extensions.has('WEBGL_multi_draw'));
62	  let mesh: THREE.InstancedMesh | THREE.BatchedMesh;
63	  if (real) {
64	    const bm = crowdBuild(crowd, list, name);
65	    for (let i = 0; i < n; i++) rnd();   // màu áo không còn tác dụng với người thật, nhưng giữ đúng một rnd() mỗi người để chuỗi của cầu không đổi
66	    // texture trong uniform: prewarm không tải trước (nó chỉ duyệt thuộc tính vật liệu) ⇒ tự tải lên GPU lúc dựng
67	    renderer.initTexture(crowd.anim); renderer.initTexture(crowd.atlas); renderer.initTexture(crowdParams(bm.material as THREE.Material));
68	    mesh = bm;
69	  } else {
70	    const geo = ppBuildGeometry(), col = new THREE.Color();
71	    const aVar = new Float32Array(n * 4), aPants = new Float32Array(n * 3);
72	    list.forEach((p, i) => {
73	      const kind = p.kind ?? 'walk';
74	      aVar.set([p.phase ?? 0, ppAmp(kind), p.flags ?? 0, ppCadence(kind, p.speed, p.scale ?? 1)], i * 4);   // pha, biên độ hông, cờ, nhịp (khớp material.ts)
75	      col.setHex(P.pants[Math.floor(ppHash(i) * P.pants.length)]); aPants.set([col.r, col.g, col.b], i * 3);   // Color chuyển hex sRGB → tuyến tính
76	    });
77	    geo.setAttribute('aVar', new THREE.InstancedBufferAttribute(aVar, 4));
78	    geo.setAttribute('aPants', new THREE.InstancedBufferAttribute(aPants, 3));
79	    const im = new THREE.InstancedMesh(geo, ppMaterial(), n);
80	    list.forEach((_p, i) => im.setColorAt(i, col.setHex(P.shirts[Math.floor(rnd() * P.shirts.length)])));   // màu áo: đúng một rnd() mỗi người như cũ
81	    im.frustumCulled = false; im.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
82	    mesh = im;
83	  }
84	  const group = new THREE.Group(); group.name = name; group.add(mesh);
85	  bridge.group.add(group); bridge.noReflect.push(group);
86	  const people: People = { list, mesh, group, real };
87	  group.userData.people = people;   // cho móc kiểm thử (environment/pedestrians.ts → peopleTest)
88	  stepPeople(people, 0, 0);   // đặt sẵn vị trí ban đầu
89	  return people;
90	}
