104	    const s = sc ? sc[i] : (p.scale ?? 1);   // người thật: tỉ lệ theo chiều cao nhân vật (crowd.ts)
105	    _pm.compose(_pv.set(p.x, p.profile(p[key]), p.z), _pq.setFromAxisAngle(UP, yaw), _ps.set(s, s, s));
106	    if (bm) { bm.setVisibleAt(i, true); bm.setMatrixAt(i, _pm); } else im.setMatrixAt(i, _pm);   // setVisibleAt / setMatrixAt của BatchedMesh tự đánh dấu cập nhật
107	  }
108	  if (im) im.instanceMatrix.needsUpdate = true;
109	}
