1	/* ===== Đi dạo: hình người khối (hình tạm khi mô hình có xương chưa nạp xong hoặc nạp lỗi) =====
2	   Một InstancedMesh 5 instance (chỉ số = slot đi dạo; đi một mình dùng 0), hình người đi bộ có sẵn (ppBuildGeometry) và vật liệu dùng chung (ppMaterial):
3	   tay chân vung trong shader theo aVar, nên đổi dáng chỉ là ghi 4 số của instance. Lớp 1 (không vào phản chiếu nước), không đổ bóng: thêm đúng 1 lệnh vẽ khi có instance hiện.
4	   Áo màu multiParams.colors[slot] (như cánh dù), quần một màu tối CONFIG.stroll.pants. Instance không hiện thu về scale 0; không instance nào hiện thì mesh.visible = false.
5	   Không có dáng nhảy (D-030); dáng rơi (3) đứng yên như bản cũ. avatars.ts quyết slot nào hiện hình khối. Không cấp phát mỗi khung (D-018). */
6	import * as THREE from 'three';
7	import { CONFIG } from '../../config';
8	import { shared } from '../../core/shared';
9	import { ppBuildGeometry } from '../../common/people/shapes';
10	import { ppMaterial } from '../../common/people/material';
11	import { ppAmp, ppCadence, ppStride } from '../../common/people/gait';
12	import { PP_FLAG } from '../../common/people/kinds';
13	import { ST_POSE_WALK, ST_POSE_RUN, ST_POSE_PHOTO } from './motion';
14	
15	const M = CONFIG.explore.multi, C = CONFIG.stroll, N = M.stroll.slots, TAU = Math.PI * 2;
16	
17	/* Thuần: dáng (pose) + tốc độ (m/s) → biên độ hông, nhịp (rad/s của φ), cờ instance (khớp aVar của material.ts).
18	   Nhịp theo tốc độ cho chân trụ không trượt (đi: bước đi; chạy: bước chạy, không chậm hơn nhịp chạy bộ), kẹp ≤ cadenceMax × run.cadence vì 3,5 / 10 m/s nhanh hơn người thật */
19	export function stAvatarVar(pose: number, speed: number, out: { amp: number; cadence: number; flags: number }): void {
20	  const cap = C.cadenceMax * CONFIG.people.run.cadence, v = Math.max(0, speed);
21	  out.amp = 0; out.cadence = 0; out.flags = 0;
22	  if (pose === ST_POSE_WALK) { out.amp = ppAmp('walk'); out.cadence = Math.min(cap, ppCadence('walk', v, 1)); }
23	  else if (pose === ST_POSE_RUN) { out.amp = ppAmp('run'); out.cadence = Math.min(cap, Math.max(ppCadence('run', v, 1), (TAU * v) / ppStride('run', 1))); }
24	  else if (pose === ST_POSE_PHOTO) out.flags = PP_FLAG.photo;
25	}
26	
27	let mesh: THREE.InstancedMesh | null = null, aVar: THREE.InstancedBufferAttribute | null = null;
28	const shown = new Uint8Array(N);                       // instance đang hiện
29	const cur = new Float32Array(N * 3).fill(-1);          // amp, cadence, flags đang ghi (để biết khi nào phải ghi lại aVar)
30	const _m = new THREE.Matrix4(), _q = new THREE.Quaternion(), _p = new THREE.Vector3(), _one = new THREE.Vector3(1, 1, 1), _zero = new THREE.Matrix4().makeScale(0, 0, 0), _up = new THREE.Vector3(0, 1, 0);
31	const _var = { amp: 0, cadence: 0, flags: 0 };
32	
33	export const stBlocky = {
34	  get mesh(): THREE.InstancedMesh | null { return mesh; },
35	  /* Instance i có đang hiện không (cho test / debug) */
36	  shown(i: number): boolean { return shown[i] === 1; },
37	
38	  /* Dựng lần đầu gọi (avatars.ts thêm vào nhóm stroll-people); các lần sau trả lại mesh cũ */
39	  build(): THREE.InstancedMesh {
40	    if (mesh) return mesh;
41	    const geo = ppBuildGeometry(), col = new THREE.Color();
42	    aVar = new THREE.InstancedBufferAttribute(new Float32Array(N * 4), 4); aVar.setUsage(THREE.DynamicDrawUsage);
43	    const pants = new Float32Array(N * 3);
44	    col.setHex(C.pants);
45	    for (let i = 0; i < N; i++) pants.set([col.r, col.g, col.b], i * 3);   // Color chuyển hex sRGB → tuyến tính
46	    geo.setAttribute('aVar', aVar);
47	    geo.setAttribute('aPants', new THREE.InstancedBufferAttribute(pants, 3));
48	    mesh = new THREE.InstancedMesh(geo, ppMaterial(), N);
49	    mesh.name = 'stroll-blocky';
50	    for (let i = 0; i < N; i++) { mesh.setColorAt(i, col.set(M.colors[i % M.colors.length])); mesh.setMatrixAt(i, _zero); }   // setColorAt bắt buộc (USE_INSTANCING_COLOR)
51	    mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
52	    mesh.layers.set(1); mesh.castShadow = false; mesh.receiveShadow = false; mesh.frustumCulled = false;
53	    shown.fill(0); cur.fill(-1); mesh.visible = false;
54	    return mesh;
55	  },
56	
57	  /* Instance i: hiện tại (x, y, z) hướng yaw với dáng pose (speed cho nhịp bước), hoặc ẩn (st = null) */
58	  place(i: number, st: { x: number; y: number; z: number; yaw: number; pose: number } | null, speed: number): void {
59	    if (!mesh || !aVar) return;
60	    if (!st) {
61	      if (!shown[i]) return;
62	      shown[i] = 0; mesh.setMatrixAt(i, _zero); mesh.instanceMatrix.needsUpdate = true;
63	      return;
64	    }
65	    shown[i] = 1;
66	    mesh.setMatrixAt(i, _m.compose(_p.set(st.x, st.y, st.z), _q.setFromAxisAngle(_up, st.yaw), _one));   // hình hướng +X: quay yaw quanh Y ra (cos yaw, 0, −sin yaw)
67	    mesh.instanceMatrix.needsUpdate = true;
68	    stAvatarVar(st.pose, speed, _var);
69	    const c = i * 3;
70	    if (_var.amp === cur[c] && _var.cadence === cur[c + 1] && _var.flags === cur[c + 2]) return;
71	    const a = aVar.array as Float32Array, o = i * 4, now = shared.uTime.value;
72	    const ph = now * a[o + 3] + a[o];   // giữ pha liền khi đổi nhịp: φ(now) không nhảy
73	    a[o] = (((ph - now * _var.cadence) % TAU) + TAU) % TAU; a[o + 1] = _var.amp; a[o + 2] = _var.flags; a[o + 3] = _var.cadence;
74	    cur[c] = _var.amp; cur[c + 1] = _var.cadence; cur[c + 2] = _var.flags;
75	    aVar.needsUpdate = true;
76	  },
77	
78	  /* Ẩn cả mesh khi không instance nào hiện (không tốn lệnh vẽ) */
79	  refresh(): void {
80	    if (!mesh) return;
81	    let any = false;
82	    for (let i = 0; i < N; i++) if (shown[i]) { any = true; break; }
83	    mesh.visible = any;
84	  }
85	};
