127	  for (const n of NAMES) {
128	    const a = p0[n], b = await positions(n);
129	    if (!a.length || a.length !== b.length) { check(false, `moving: ${n} không đọc được vị trí`); continue; }
130	    let moved = 0, still = 0, badHead = 0, tilted = 0;
131	    const stands = b.filter((p) => p.kind === 'stand').length;
132	    b.forEach((p, i) => {
133	      const dx = p.x - a[i].x, dz = p.z - a[i].z, d = Math.hypot(dx, dz);
134	      if (d > 0.01) moved++; else still++;
135	      if (p.upY < 0.999) tilted++;
136	      if (d > 0.01 && d < 10 && (p.fwd[0] * dx + p.fwd[2] * dz) / d < 0.95) badHead++;   // bỏ qua người vừa quay vòng về đầu dải
137	    });
138	    check(moved >= 0.6 * b.length, `moving: ${n} ${moved}/${b.length} người đã đổi vị trí sau 60 khung`);
139	    check(Math.abs(still - stands) <= 1, `moving: ${n} ${still} người đứng yên, ${stands} người kiểu 'stand'`);
140	    check(tilted === 0 && badHead === 0, `moving: ${n} mọi người thẳng đứng (${tilted} nghiêng), quay mặt theo chiều đi (${badHead} sai hướng)`);
