test('tệp có chỉ số ngoài khoảng bị từ chối', () => {
  const src = readFileSync(BIN), J = src.readUInt32LE(8), meta = JSON.parse(src.subarray(12, 12 + J).toString('utf8')), bin = src.subarray(12 + J);
